    "development": {
      "NVDA-0001045810-26-000075-r2": "candidate: spelled_quantities empty, rating_outperform_min and rating_underperform_max present, no gate_note blocker; baseline expected to show spelled quantities (e.g. 'fifteen percent') and/or missing placeholders",
